using HeadlessCMS.API.Extensions;
using HeadlessCMS.Data;

DotNetEnv.Env.Load();

var builder = WebApplication.CreateBuilder(args);

builder.Logging.AddLogshipFromConfiguration(builder.Configuration, builder.Environment);

// Learn more about configuring OpenAPI at https://aka.ms/aspnet/openapi
builder.Services.AddOpenApi(options =>
{
    options.AddDocumentTransformer((document, context, cancellationToken) =>
    {
        // Clear any autogenerated internal HTTP URLs (like http://localhost:8080)
        document.Servers.Clear();

        // Force relative pathing so Swagger UI uses current HTTPS origin
        document.Servers.Add(new Microsoft.OpenApi.Models.OpenApiServer
        {
            Url = "/"
        });

        return Task.CompletedTask;
    });
});

builder.Services.AddDataServices(builder.Configuration, builder.Environment);

var app = builder.Build();

app.UseHttpsRedirection();

// Triggers the Redis ping and EF Core migration check inside Configuration.cs
await app.Services.InitDataServicesAsync();

app.MapOpenApi();

app.UseSwaggerUI(options =>
{
    options.SwaggerEndpoint("/openapi/v1.json", "HeadlessCMS API");
    options.RoutePrefix = "documentation";
});

app.MapGet("/", () => "Hello World");

app.Run();
